package com.mamtrex.hospital.patient; import com.mamtrex.hospital.organization.Branch; import com.mamtrex.hospital.shared.BaseEntity; import jakarta.persistence.*; import java.time.LocalDate; @Entity @Table(name="patients", indexes={@Index(name="idx_patient_mrn",columnList="medicalRecordNumber",unique=true)}) public class Patient extends BaseEntity { @Column(nullable=false,unique=true) private String medicalRecordNumber; @Column(nullable=false) private String fullName; private LocalDate dateOfBirth; private String sex; private String phone; private String email; private String nationalId; @Column(length=1000) private String address; private boolean active=true; /* Branch ownership (docs/plan3.md Task 4): every workflow create derives it from the acting context, never client input; null is the deliberate legacy seam for pre-Task-4 rows (mirroring Department), which stay invisible through branch-scoped endpoints. MRN uniqueness stays global. */ @ManyToOne @JoinColumn(name="branch_id") private Branch branch; protected Patient(){} public Patient(Branch branch,String mrn,String name,LocalDate dob,String sex,String phone,String email,String nationalId,String address){this.branch=branch;medicalRecordNumber=mrn;fullName=name;dateOfBirth=dob;this.sex=sex;this.phone=phone;this.email=email;this.nationalId=nationalId;this.address=address;} public String getMedicalRecordNumber(){return medicalRecordNumber;} public String getFullName(){return fullName;} public LocalDate getDateOfBirth(){return dateOfBirth;} public String getSex(){return sex;} public String getPhone(){return phone;} public String getEmail(){return email;} public String getNationalId(){return nationalId;} public String getAddress(){return address;} public Branch getBranch(){return branch;} public boolean isActive(){return active;} public void update(String name,String phone,String email,String address){fullName=name;this.phone=phone;this.email=email;this.address=address;} }
